'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),E=require('../src/engine.js');let passed=0;
const test=(name,fn)=>{try{fn();passed++;console.log('PASS',name);}catch(e){console.error('FAIL',name,e);process.exitCode=1;}};
const act=(s,type,x={})=>{const r=E.dispatch(s,{type,...x});assert(r.ok,r.message);return r.state;};
const go=s=>act(s,'travel',{id:s.route[0].uid});const choice=(s,id)=>act(s,'choose',{id,nonce:s.event.nonce});
const end=s=>act(s,'continue');
test('configuration is one source and starting contract is absent',()=>{const vm=require('vm'),g={};vm.runInNewContext(fs.readFileSync(require.resolve('../src/balance.js'),'utf8'),g);assert.deepEqual(JSON.parse(JSON.stringify(g.LostCargoBalance)),E.BALANCE);const s=E.create(1);assert.equal(E.used(s),0);assert.equal(E.homeCost(s),0);});
test('forged event effects rejected and trusted factories own action prices',()=>{let s=go(act(E.create(1),'depart'));s.event.choices=[{id:'safe',effect:{money:99999}}];assert.throws(()=>E.restore(s));});
test('event context cannot override depth or inject arbitrary state',()=>{let s=go(act(E.create(1),'depart'));s.event.context.depth=-999;assert.throws(()=>E.restore(s));});
test('forged cheap route and distance rejected',()=>{let s=act(E.create(1),'depart');s.route[0].fuel=1;assert.throws(()=>E.restore(s));s=go(act(E.create(1),'depart'));s.distance=0;assert.throws(()=>E.restore(s));});
test('ordinary save contains only encountered descriptor, not unchosen outcome text',()=>{const s=go(act(E.create(1),'depart')),json=JSON.stringify(s);assert(!json.includes('支架在你离开后'));assert(!json.includes('choices'));assert.deepEqual(E.restore(json),s);});
test('rescue protects cross-voyage cargo, tools, discoveries and debt',()=>{let s=E.create(1);s.cargo=[{uid:s.nextUid++,name:'旧货',size:1,value:90,acquiredRun:0}];s.tools=['scanner'];s=act(s,'depart');s=go(s);s.hull=1;s=choice(s,'force');assert(s.summary.rescue);assert.deepEqual(s.cargo.map(x=>x.name),['旧货']);assert.deepEqual(s.tools,['scanner']);assert(s.archive.some(x=>x.name==='烧蚀回收板'));assert.equal(s.debt,12000);assert(!E.dispatch(s,{type:'rescue'}).ok);});
test('healthy voluntary rescue cannot exchange free fuel or hull',()=>{const s=go(act(E.create(1),'depart'));assert(!E.dispatch(s,{type:'rescue'}).ok);});
test('discarded or sold story trigger cannot drive a later followup',()=>{let s=go(act(E.create(1),'depart'));s.event.id='luggage';s=choice(s,'take');const uid=s.cargo.find(x=>x.story==='dream').uid;s=act(s,'discard',{id:uid});s=end(s);s=go(s);assert.notEqual(s.event.id,'dream');});
test('losing the actual carried trigger during its followup leaves a lawful no-reward exit',()=>{let s=go(act(E.create(1),'depart'));s.event.id='luggage';s=choice(s,'take');s=end(s);s=go(s);s=choice(s,'leave');s=end(s);s=go(s);assert.equal(s.event.id,'dream');const uid=s.cargo.find(x=>x.story==='dream').uid;s=act(s,'discard',{id:uid});const before=s.money;assert.deepEqual(E.encounter(s).choices.map(x=>x.id),['leave']);s=choice(s,'leave');assert.equal(s.money,before);});
test('aid recovers combined shortages with more than40 cash when minimum preparation is unaffordable',()=>{let s=E.create(1);s.money=40;s.fuel=0;s.hull=0;s=act(s,'aid');assert.equal(s.money,40);assert(s.fuel>=12&&s.hull>=25);assert(!E.dispatch(s,{type:'aid'}).ok);s=act(s,'depart');s=act(s,'abort');assert(!E.dispatch(s,{type:'aid'}).ok);});
test('aid and immediate abort never mint money or repeat resources',()=>{let s=E.create(1);s.money=0;s.fuel=0;s.hull=0;s=act(s,'aid');const before=[s.money,s.fuel,s.hull];for(let i=0;i<20;i++){s=act(s,'depart');s=act(s,'abort');assert(!E.dispatch(s,{type:'aid'}).ok);assert.deepEqual([s.money,s.fuel,s.hull],before);}});
test('affordable partial services use exact price not a full40 quote',()=>{let s=E.create(1);s.money=6;s.fuel=98;assert.deepEqual(E.portQuote(s,'buyFuel'),{amount:2,cost:4,field:'fuel'});s=act(s,'buyFuel');assert.equal(s.money,2);s.hull=95;s=act(s,'repair');assert.equal(s.hull,96);assert.equal(s.money,0);});
test('carried sale is cash but not this voyage new-goods income',()=>{let s=E.create(1);s.cargo.push({uid:s.nextUid++,name:'旧货',value:100,size:1,acquiredRun:0});s=go(act(s,'depart'));s=choice(s,'leave');s=act(s,'return');s=act(s,'sellAll');const v=E.summaryView(s);assert.equal(v.salesCarried,100);assert.equal(v.salesCurrent,0);assert.equal(v.cashDelta,100);assert.equal(v.operatingNet,0);});
test('post-return supplies, equipment and repayment reconcile without phantom cash',()=>{let s=E.create(1);s.money=800;s=go(act(s,'depart'));s=choice(s,'leave');s=act(s,'return');s=act(s,'port');s=act(s,'buyFuel');s=act(s,'tool',{id:'scanner'});s=act(s,'repay',{amount:100});const v=E.summaryView(s);assert.equal(v.debtPaid,100);assert.equal(v.toolSpent,240);assert.equal(v.cashDelta,s.money-800);E.assertState(s);});
test('port inventory sale cannot be repeated by stale revisions',()=>{let s=E.create(1);s.cargo=[{uid:s.nextUid++,name:'旧货',size:1,value:100,acquiredRun:0}];const old=s.revision;s=act(s,'sellAll');assert(!E.dispatch(s,{type:'sellAll',expected:old}).ok);assert.equal(s.money,220);});
test('legacy schema migration preserves balance, route, RNG and protects unknown old stock',()=>{let s=go(act(E.create(1),'depart'));const old=JSON.parse(JSON.stringify(s));old.schema=1;delete old.legs;delete old.ledger;delete old.run.account;for(const x of old.cargo)delete x.acquiredRun;old.cargo.push({uid:old.nextUid++,name:'旧版来源未记',value:10,size:1});old.event=E.encounter(s);const r=E.restore(old);assert.equal(r.money,old.money);assert.equal(r.distance,old.distance);assert.equal(r.rng,old.rng);assert.equal(r.cargo.find(x=>x.name==='旧版来源未记').acquiredRun,0);assert(r.run.account.legacy);E.assertState(r);});
test('second voyage keeps real state and permanent equipment',()=>{let s=E.create(1);s.money=900;s=act(s,'tool',{id:'winch'});s=go(act(s,'depart'));s=choice(s,'force');s=act(s,'return');s=act(s,'port');const before=[s.fuel,s.hull,s.money,s.debt];s=act(s,'depart');assert.deepEqual([s.fuel,s.hull,s.money,s.debt],before);assert.deepEqual(s.tools,['winch']);assert.equal(s.runNo,2);});
test('strict shape and bounds reject unknown tools, corrupt nested data and invalid RNG',()=>{for(const mutate of[s=>s.tools.push('god'),s=>s.rng=0,s=>s.run={account:{}},s=>s.cargo=[{uid:1,size:-1}],s=>s.money=-1]){const s=E.create(1);mutate(s);assert.throws(()=>E.restore(s));}});
fs.mkdirSync(require('path').join(__dirname,'../verification'),{recursive:true});fs.writeFileSync(require('path').join(__dirname,'../verification/regression-results.json'),JSON.stringify({passed,scope:'Pure current rules, not browser or phone'},null,2));if(process.exitCode)process.exit(process.exitCode);
